from csvjson import _quoted_mask


def quoted_mask(csv_text):
    """Per-record list of booleans: was field i quoted in the source?

    Independent re-implementation of the documented scan mechanism so the
    tests do not just trust csvjson's own code path.
    """
    masks = []
    i, n = 0, len(csv_text)
    while i < n:
        rec_start = i
        row = []
        while True:
            quoted = i < n and csv_text[i] == '"'
            if quoted:
                i += 1
                while i < n:
                    if csv_text[i] == '"':
                        if i + 1 < n and csv_text[i + 1] == '"':
                            i += 2
                            continue
                        i += 1
                        break
                    i += 1
            while i < n and csv_text[i] not in ',\r\n':
                i += 1
            row.append(quoted)
            if i < n and csv_text[i] == ',':
                i += 1
                continue
            break
        if not (row == [False] and i == rec_start):
            masks.append(row)
        if i < n and csv_text[i] == '\r':
            i += 1
        if i < n and csv_text[i] == '\n':
            i += 1
    assert masks == _quoted_mask(csv_text)
    return masks

